class ProgressService:
    def __init__(self, completed):
        self.completed = completed

    def complete(self, lesson_id):
        if not isinstance(lesson_id, str) or not lesson_id.strip():
            raise ValueError('lesson_id is required')
        lesson_id = lesson_id.strip()
        already_done = lesson_id in self.completed
        self.completed.add(lesson_id)
        return {'lesson_id': lesson_id, 'already_done': already_done}

items = set()
service = ProgressService(items)
assert service.complete('loops')['already_done'] is False
assert service.complete(' loops ')['already_done'] is True
assert items == {'loops'}
